CREATE TABLE `resident` (
  `resident_id` int NOT NULL AUTO_INCREMENT,
  `barangay_id` int NOT NULL,
  `household_id` int DEFAULT NULL,
  `purok_id` int NOT NULL,
  `last_name` varchar(100) NOT NULL,
  `first_name` varchar(100) NOT NULL,
  `middle_name` varchar(100) DEFAULT NULL,
  `suffix` varchar(20) DEFAULT NULL,
  `sex` enum('M','F') NOT NULL,
  `birth_date` date NOT NULL,
  `birth_place` varchar(150) DEFAULT NULL,
  `civil_status` enum('Single','Married','Widowed','Separated') DEFAULT NULL,
  `citizenship` varchar(100) DEFAULT 'Filipino',
  `religion` varchar(100) DEFAULT NULL,
  `contact_no` varchar(50) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `occupation` varchar(150) DEFAULT NULL,
  `employer` varchar(150) DEFAULT NULL,
  `education_level` varchar(100) DEFAULT NULL,
  `is_pwd` tinyint(1) DEFAULT '0',
  `pwd_id_no` varchar(100) DEFAULT NULL,
  `is_senior` tinyint(1) DEFAULT '0',
  `is_4ps_beneficiary` tinyint(1) DEFAULT '0',
  `is_registered_voter` tinyint(1) DEFAULT '0',
  `voter_precinct_no` varchar(50) DEFAULT NULL,
  `status` enum('ACTIVE','DECEASED','MOVED_OUT') DEFAULT 'ACTIVE',
  `date_registered` date DEFAULT (curdate()),
  `photo_url` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `photo` longblob,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by_user_id` int DEFAULT NULL,
  `delete_reason` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`resident_id`),
  KEY `household_id` (`household_id`),
  KEY `idx_resident_name` (`last_name`,`first_name`,`middle_name`),
  KEY `idx_resident_barangay` (`barangay_id`),
  KEY `idx_resident_purok` (`purok_id`),
  KEY `idx_resident_status` (`status`),
  CONSTRAINT `resident_ibfk_1` FOREIGN KEY (`barangay_id`) REFERENCES `barangay` (`barangay_id`) ON DELETE CASCADE,
  CONSTRAINT `resident_ibfk_2` FOREIGN KEY (`household_id`) REFERENCES `household` (`household_id`) ON DELETE SET NULL,
  CONSTRAINT `resident_ibfk_3` FOREIGN KEY (`purok_id`) REFERENCES `purok_sitio` (`purok_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
